window.JA_GLOSSARY=[{"term": "exploit", "ja": "エクスプロイト", "desc": "ソフトウェアの脆弱性を突いて、作者が想定していない動作をさせるプログラムや手順。", "aliases": ["exploits", "exploitation"]}, {"term": "payload", "ja": "ペイロード", "desc": "攻撃で、相手に送り込む本体のデータ。たとえば、実行させたいコード。", "aliases": ["payloads"]}, {"term": "shellcode", "ja": "シェルコード", "desc": "攻撃で相手に実行させる、小さな機械語のコード。多くは、シェル（操作用の画面）を起動する。", "aliases": ["shellcodes"]}, {"term": "ASLR", "ja": "ASLR", "desc": "プログラムやライブラリを置くメモリの場所を、起動のたびにランダムに変える防御。攻撃者が、アドレスを当てにくくなる。", "url": "https://csrc.nist.gov/glossary/term/address_space_layout_randomization", "src": "NIST 用語集（英語）"}, {"term": "setuid", "ja": "setuid", "desc": "実行した人ではなく、ファイルの持ち主の権限で動くようにする、Unix のしくみ。", "url": "https://man7.org/linux/man-pages/man7/credentials.7.html", "src": "Linux man ページ（英語）"}, {"term": "EOF", "ja": "EOF（入力の終わり）", "desc": "End Of File の略。これ以上、読めるデータがないこと。"}, {"term": "tty", "ja": "TTY（端末）", "desc": "キーボードで入力して、文字で結果を見る、端末のこと。", "aliases": ["TTY", "pty"], "url": "https://man7.org/linux/man-pages/man7/pty.7.html", "src": "Linux man ページ（英語）"}, {"term": "ELF", "ja": "ELF", "desc": "Linux などで使う、実行ファイルの形式。", "url": "https://man7.org/linux/man-pages/man5/elf.5.html", "src": "Linux man ページ（英語）"}, {"term": "libc", "ja": "libc", "desc": "多くのプログラムが共通で使う、C 言語の標準ライブラリ。", "url": "https://www.gnu.org/software/libc/manual/html_node/index.html", "src": "GNU C ライブラリのマニュアル（英語）"}, {"term": "endianness", "ja": "エンディアン", "desc": "複数バイトの数を、メモリにどの順で並べるか。小さい桁から並べるのが little、大きい桁からが big。", "aliases": ["endian"]}, {"term": "fuzzing", "ja": "ファジング", "desc": "でたらめに近いデータを大量に与えて、プログラムが壊れる場所を探す手法。", "aliases": ["fuzzer"], "url": "https://owasp.org/www-community/Fuzzing", "src": "OWASP（英語）"}, {"term": "CVE", "ja": "CVE", "desc": "脆弱性につけられる、世界共通の番号（例: CVE-2024-0001）。", "url": "https://www.cve.org/", "src": "CVE プログラム公式（英語）"}];
